//! Lookups in the ISBN range table (registration groups and registrant ranges).
//!
//! The table itself lives in `ranges_data.rs`, generated by `tools/gen_ranges.py` from a
//! snapshot of the International ISBN Agency's `RangeMessage`.

use crate::ranges_data::GROUPS;

/// A contiguous block of registrant numbers that all have the same length.
#[derive(Debug, Clone, Copy)]
pub(crate) struct Range {
    /// Registrant length in the top byte, lower bound in the low 24 bits.
    len_lo: u32,
    /// Upper bound (inclusive), as a `len`-digit number.
    hi: u32,
}

impl Range {
    /// Number of digits of the registrant element in this range (1..=7).
    pub(crate) const fn len(&self) -> usize {
        (self.len_lo >> 24) as usize
    }

    /// Lower bound (inclusive), as a `len`-digit number.
    pub(crate) const fn lo(&self) -> u32 {
        self.len_lo & 0x00ff_ffff
    }

    /// Upper bound (inclusive), as a `len`-digit number.
    pub(crate) const fn hi(&self) -> u32 {
        self.hi
    }

    /// `10^(7 - len)`: scales a `len`-digit bound to the 7-digit space the table is sorted in.
    const fn scale(&self) -> u32 {
        10u32.pow(7 - (self.len_lo >> 24))
    }

    /// Lower bound in the 7-digit registrant space.
    pub(crate) const fn lo7(&self) -> u32 {
        self.lo() * self.scale()
    }

    /// Upper bound (inclusive) in the 7-digit registrant space.
    pub(crate) const fn hi7(&self) -> u32 {
        self.hi() * self.scale() + self.scale() - 1
    }
}

/// Builds a [`Range`]; used by the generated table.
pub(crate) const fn r(len: u8, lo: u32, hi: u32) -> Range {
    assert!(len >= 1 && len <= 7 && lo <= hi && hi < 10u32.pow(len as u32));
    Range { len_lo: ((len as u32) << 24) | lo, hi }
}

/// One registration group (language area, country or territory) and its registrant ranges.
#[derive(Debug)]
pub(crate) struct Group {
    /// GS1 prefix: 978 or 979.
    pub(crate) gs1: u16,
    /// Number of digits of the group element (1..=5 in practice).
    pub(crate) len: u8,
    /// The group element as a number.
    pub(crate) number: u32,
    /// `"978-2"`.
    pub(crate) prefix: &'static str,
    /// Agency name, e.g. `"French language"`.
    pub(crate) name: &'static str,
    /// Registrant ranges sorted by their position in the 7-digit registrant space.
    pub(crate) ranges: &'static [Range],
}

/// Builds a [`Group`]; used by the generated table.
pub(crate) const fn g(
    gs1: u16,
    len: u8,
    number: u32,
    prefix: &'static str,
    name: &'static str,
    ranges: &'static [Range],
) -> Group {
    Group { gs1, len, number, prefix, name, ranges }
}

/// Longest group element in the table, in digits.
const MAX_GROUP_LEN: usize = 7;

/// The registration group an ISBN belongs to: a language area, country or territory.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct RegistrationGroup {
    /// GS1 prefix and group element joined by a hyphen, e.g. `"978-2"` or `"979-10"`.
    pub prefix: &'static str,
    /// Name of the area as published by the International ISBN Agency, e.g.
    /// `"French language"`, `"Italy"`.
    pub name: &'static str,
}

impl RegistrationGroup {
    /// The GS1 prefix of the group: `978` or `979`.
    #[must_use]
    pub fn gs1_prefix(&self) -> u16 {
        if self.prefix.starts_with("979") { 979 } else { 978 }
    }

    /// The group element alone, e.g. `"2"` for `"978-2"`.
    #[must_use]
    pub fn group(&self) -> &'static str {
        self.prefix.split_once('-').map_or("", |(_, group)| group)
    }

    /// Every registration group in the embedded table, ordered by GS1 prefix, then group
    /// length, then group number.
    pub fn all() -> impl Iterator<Item = RegistrationGroup> {
        GROUPS.iter().map(|g| RegistrationGroup { prefix: g.prefix, name: g.name })
    }
}

/// How an ISBN-13 splits into its elements.
#[derive(Debug, Clone, Copy)]
pub(crate) struct Split {
    /// The registration group.
    pub(crate) group: &'static Group,
    /// Digits of the registrant element, when the registrant range is assigned.
    pub(crate) registrant_len: Option<usize>,
}

/// Reads `len` digits starting at `start` as a number.
fn number(digits: &[u8; 13], start: usize, len: usize) -> u32 {
    digits.iter().skip(start).take(len).fold(0u32, |acc, d| acc * 10 + u32::from(*d))
}

/// Finds the registration group of thirteen ISBN digits (values `0..=9`).
pub(crate) fn find_group(digits: &[u8; 13]) -> Option<&'static Group> {
    let gs1 = number(digits, 0, 3) as u16;
    // Group prefixes are prefix-free (checked by the generator and by a test), so the first
    // length that matches is the only one.
    (1..=MAX_GROUP_LEN).find_map(|len| {
        let key = (gs1, len as u8, number(digits, 3, len));
        GROUPS.binary_search_by(|g| (g.gs1, g.len, g.number).cmp(&key)).ok().map(|i| &GROUPS[i])
    })
}

/// Splits thirteen ISBN digits (values `0..=9`) into group and registrant.
pub(crate) fn split(digits: &[u8; 13]) -> Option<Split> {
    let group = find_group(digits)?;
    let after_group = 3 + usize::from(group.len);
    // The first seven digits after the group, zero-padded when fewer remain before the
    // check digit. Padding never matters: a range of length `n` only looks at `n` digits
    // and the generator guarantees `group.len + n <= 8`.
    let available = 12usize.saturating_sub(after_group).min(7);
    let v7 = number(digits, after_group, available) * 10u32.pow((7 - available) as u32);
    let idx = group.ranges.partition_point(|r| r.lo7() <= v7);
    let registrant_len = idx
        .checked_sub(1)
        .and_then(|i| group.ranges.get(i))
        .filter(|r| v7 <= r.hi7() && after_group + r.len() < 12)
        .map(Range::len);
    Some(Split { group, registrant_len })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_sorted_and_prefix_free() {
        for pair in GROUPS.windows(2) {
            let a = (pair[0].gs1, pair[0].len, pair[0].number);
            let b = (pair[1].gs1, pair[1].len, pair[1].number);
            assert!(a < b, "groups out of order: {} then {}", pair[0].prefix, pair[1].prefix);
        }
        for a in &GROUPS {
            assert!(a.gs1 == 978 || a.gs1 == 979);
            assert!((1..=MAX_GROUP_LEN).contains(&usize::from(a.len)));
            let expected = format!("{}-{:0width$}", a.gs1, a.number, width = usize::from(a.len));
            assert_eq!(a.prefix, expected);
            assert!(!a.name.trim().is_empty(), "{} has no name", a.prefix);
            for b in &GROUPS {
                if a.prefix != b.prefix {
                    assert!(
                        !b.prefix.starts_with(a.prefix),
                        "{} is a prefix of {}",
                        a.prefix,
                        b.prefix
                    );
                }
            }
        }
    }

    #[test]
    fn ranges_are_sorted_disjoint_and_leave_a_publication_digit() {
        for group in &GROUPS {
            let mut previous_end: Option<u32> = None;
            for range in group.ranges {
                assert!((1..=7).contains(&range.len()), "{}", group.prefix);
                assert!(range.lo() <= range.hi(), "{}", group.prefix);
                assert!(range.hi() < 10u32.pow(range.len() as u32), "{}", group.prefix);
                assert!(usize::from(group.len) + range.len() <= 8, "{}", group.prefix);
                if let Some(end) = previous_end {
                    assert!(range.lo7() > end, "overlap in {}", group.prefix);
                }
                previous_end = Some(range.hi7());
            }
        }
    }

    /// Builds the ISBN whose registrant starts with `registrant` (a `len`-digit number) in
    /// `group`, with every remaining digit set to `fill`.
    fn isbn_in(group: &Group, registrant: u32, len: usize, fill: u8) -> crate::Isbn13 {
        let mut body = format!(
            "{}{:0glen$}{:0len$}",
            group.gs1,
            group.number,
            registrant,
            glen = usize::from(group.len)
        );
        while body.len() < 12 {
            body.push(char::from(b'0' + fill));
        }
        let mut first12 = [0u8; 12];
        first12.copy_from_slice(body.as_bytes());
        let plain = format!("{body}{}", crate::ean13_check_digit(&first12));
        crate::Isbn13::parse(&plain).expect("valid by construction")
    }

    #[test]
    fn every_range_bound_hyphenates_with_the_structure_the_table_says() {
        let mut checked = 0usize;
        for group in &GROUPS {
            for range in group.ranges {
                let middle = range.lo() + (range.hi() - range.lo()) / 2;
                for (registrant, fill) in [
                    (range.lo(), 0),
                    (range.lo(), 9),
                    (middle, 5),
                    (range.hi(), 0),
                    (range.hi(), 9),
                ] {
                    let isbn = isbn_in(group, registrant, range.len(), fill);
                    let hyphenated = isbn.hyphenated();
                    let elements: Vec<&str> = hyphenated.split('-').collect();
                    assert_eq!(elements.len(), 5, "{hyphenated}");
                    assert_eq!(format!("{}-{}", elements[0], elements[1]), group.prefix);
                    assert_eq!(elements[2].len(), range.len(), "{hyphenated}");
                    assert_eq!(elements[2].parse::<u32>().ok(), Some(registrant), "{hyphenated}");
                    assert!(!elements[3].is_empty(), "{hyphenated}");
                    assert_eq!(elements[4].len(), 1, "{hyphenated}");
                    assert_eq!(hyphenated.replace('-', ""), isbn.to_plain());
                    assert_eq!(crate::Isbn13::parse(&hyphenated), Ok(isbn));
                    assert_eq!(
                        isbn.registration_group().map(|g| (g.prefix, g.name)),
                        Some((group.prefix, group.name))
                    );
                    checked += 1;
                }
            }
        }
        assert!(checked > 5_000, "only {checked} cases");
    }

    #[test]
    fn gaps_between_ranges_are_left_unhyphenated() {
        let mut gaps = 0usize;
        for group in &GROUPS {
            // Just below the first range, between consecutive ranges, and above the last.
            let mut probes: Vec<u32> = Vec::new();
            if let Some(first) = group.ranges.first()
                && first.lo7() > 0
            {
                probes.push(first.lo7() - 1);
            }
            for pair in group.ranges.windows(2) {
                if pair[1].lo7() > pair[0].hi7() + 1 {
                    probes.push(pair[0].hi7() + 1);
                    probes.push(pair[1].lo7() - 1);
                }
            }
            if let Some(last) = group.ranges.last()
                && last.hi7() < 9_999_999
            {
                probes.push(last.hi7() + 1);
            }
            for v7 in probes {
                // Only the digits that exist before the check digit can be probed.
                let available = (9 - usize::from(group.len)).min(7);
                let registrant = v7 / 10u32.pow((7 - available) as u32);
                let isbn = isbn_in(group, registrant, available, 0);
                if split(&isbn.digits()).and_then(|s| s.registrant_len).is_none() {
                    assert_eq!(isbn.hyphenated(), isbn.to_plain());
                    assert_eq!(isbn.parts(), None);
                    gaps += 1;
                }
            }
        }
        assert!(gaps > 100, "only {gaps} gaps probed");
    }

    #[test]
    fn table_has_the_expected_coverage() {
        assert!(GROUPS.len() >= 250, "table looks truncated: {} groups", GROUPS.len());
        for prefix in [
            "978-0", "978-1", "978-2", "978-3", "978-4", "978-5", "978-7", "978-84", "978-88",
            "978-90", "978-972", "979-8", "979-10", "979-11", "979-12", "979-13",
        ] {
            assert!(GROUPS.iter().any(|g| g.prefix == prefix), "missing group {prefix}");
        }
    }

    #[test]
    fn registration_group_accessors() {
        let fr = RegistrationGroup::all().find(|g| g.prefix == "979-10").expect("979-10 exists");
        assert_eq!(fr.gs1_prefix(), 979);
        assert_eq!(fr.group(), "10");
        assert_eq!(fr.name, "France");
        let en = RegistrationGroup::all().next().expect("non-empty");
        assert_eq!((en.prefix, en.gs1_prefix(), en.group()), ("978-0", 978, "0"));
        assert_eq!(RegistrationGroup::all().count(), GROUPS.len());
    }
}
